PRAGMA recursive_triggers=OFF; CREATE TEMP TABLE tbl(a,b); CREATE INDEX tbl_idx ON tbl(b); CREATE TEMP TRIGGER insert_before_row BEFORE INSERT ON tbl FOR EACH ROW BEGIN INSERT INTO rlog VALUES((SELECT coalesce(max(idx),0)+1 FROM rlog),0,0,(SELECT coalesce(sum(a),0) FROM tbl),(SELECT coalesce(sum(b),0) FROM tbl),new.a,new.b); END; CREATE TEMP TRIGGER insert_after_row AFTER INSERT ON tbl FOR EACH ROW BEGIN INSERT INTO rlog VALUES((SELECT coalesce(max(idx),0)+1 FROM rlog),0,0,(SELECT coalesce(sum(a),0) FROM tbl),(SELECT coalesce(sum(b),0) FROM tbl),new.a,new.b); END; CREATE TABLE other_tbl(a,b); INSERT INTO other_tbl VALUES(1,2); INSERT INTO other_tbl VALUES(3,4); INSERT INTO tbl VALUES(5,6); DROP TABLE other_tbl;